    /// Runner → server.
    public enum RunnerMessage: Codable, Hashable, Sendable {
        case hello(RunnerMessageHello)
        case health(RunnerMessageHealth)
        case sessionOpened(RunnerMessageSessionOpened)
        case sessionError(RunnerMessageSessionError)
        case sessionEnded(RunnerMessageSessionEnded)
        case sessionActivity(RunnerMessageSessionActivity)
        case sessionEvents(RunnerMessageSessionEvents)
        case sessionReplay(RunnerMessageSessionReplay)
        case updateStatus(RunnerMessageUpdateStatus)
        case agentLoginStatus(RunnerMessageAgentLoginStatus)
        case usage(RunnerMessageUsage)
        case sessionCost(RunnerMessageSessionCost)
        case mcpRequest(RunnerMessageMcpRequest)
        case taskStarted(RunnerMessageTaskStarted)
        case taskFinished(RunnerMessageTaskFinished)
        case taskDiff(RunnerMessageTaskDiff)
        case taskMerged(RunnerMessageTaskMerged)
        case taskMergeCheck(RunnerMessageTaskMergeCheck)
        case taskHandedOff(RunnerMessageTaskHandedOff)
        case draftProgress(RunnerMessageDraftProgress)
        case draftDone(RunnerMessageDraftDone)
        case taskProgress(RunnerMessageTaskProgress)
        case taskCleaned(RunnerMessageTaskCleaned)
        case taskTokenRequest(RunnerMessageTaskTokenRequest)
        case secretsRequest(RunnerMessageSecretsRequest)
        /// A message this build doesn't know yet; newer servers and runners may send them.
        case unknown(String)

        private enum TypeKey: String, CodingKey { case type }

        public init(from decoder: Decoder) throws {
            let type = try decoder.container(keyedBy: TypeKey.self).decode(String.self, forKey: .type)
            switch type {
            case "hello": self = .hello(try RunnerMessageHello(from: decoder))
            case "health": self = .health(try RunnerMessageHealth(from: decoder))
            case "session.opened": self = .sessionOpened(try RunnerMessageSessionOpened(from: decoder))
            case "session.error": self = .sessionError(try RunnerMessageSessionError(from: decoder))
            case "session.ended": self = .sessionEnded(try RunnerMessageSessionEnded(from: decoder))
            case "session.activity": self = .sessionActivity(try RunnerMessageSessionActivity(from: decoder))
            case "session.events": self = .sessionEvents(try RunnerMessageSessionEvents(from: decoder))
            case "session.replay": self = .sessionReplay(try RunnerMessageSessionReplay(from: decoder))
            case "update.status": self = .updateStatus(try RunnerMessageUpdateStatus(from: decoder))
            case "agent.login_status": self = .agentLoginStatus(try RunnerMessageAgentLoginStatus(from: decoder))
            case "usage": self = .usage(try RunnerMessageUsage(from: decoder))
            case "session.cost": self = .sessionCost(try RunnerMessageSessionCost(from: decoder))
            case "mcp.request": self = .mcpRequest(try RunnerMessageMcpRequest(from: decoder))
            case "task.started": self = .taskStarted(try RunnerMessageTaskStarted(from: decoder))
            case "task.finished": self = .taskFinished(try RunnerMessageTaskFinished(from: decoder))
            case "task.diff": self = .taskDiff(try RunnerMessageTaskDiff(from: decoder))
            case "task.merged": self = .taskMerged(try RunnerMessageTaskMerged(from: decoder))
            case "task.merge_check": self = .taskMergeCheck(try RunnerMessageTaskMergeCheck(from: decoder))
            case "task.handed_off": self = .taskHandedOff(try RunnerMessageTaskHandedOff(from: decoder))
            case "draft.progress": self = .draftProgress(try RunnerMessageDraftProgress(from: decoder))
            case "draft.done": self = .draftDone(try RunnerMessageDraftDone(from: decoder))
            case "task.progress": self = .taskProgress(try RunnerMessageTaskProgress(from: decoder))
            case "task.cleaned": self = .taskCleaned(try RunnerMessageTaskCleaned(from: decoder))
            case "task.token_request": self = .taskTokenRequest(try RunnerMessageTaskTokenRequest(from: decoder))
            case "secrets.request": self = .secretsRequest(try RunnerMessageSecretsRequest(from: decoder))
            default: self = .unknown(type)
            }
        }

        public func encode(to encoder: Encoder) throws {
            var c = encoder.container(keyedBy: TypeKey.self)
            switch self {
            case .hello(let body):
                try c.encode("hello", forKey: .type)
                try body.encode(to: encoder)
            case .health(let body):
                try c.encode("health", forKey: .type)
                try body.encode(to: encoder)
            case .sessionOpened(let body):
                try c.encode("session.opened", forKey: .type)
                try body.encode(to: encoder)
            case .sessionError(let body):
                try c.encode("session.error", forKey: .type)
                try body.encode(to: encoder)
            case .sessionEnded(let body):
                try c.encode("session.ended", forKey: .type)
                try body.encode(to: encoder)
            case .sessionActivity(let body):
                try c.encode("session.activity", forKey: .type)
                try body.encode(to: encoder)
            case .sessionEvents(let body):
                try c.encode("session.events", forKey: .type)
                try body.encode(to: encoder)
            case .sessionReplay(let body):
                try c.encode("session.replay", forKey: .type)
                try body.encode(to: encoder)
            case .updateStatus(let body):
                try c.encode("update.status", forKey: .type)
                try body.encode(to: encoder)
            case .agentLoginStatus(let body):
                try c.encode("agent.login_status", forKey: .type)
                try body.encode(to: encoder)
            case .usage(let body):
                try c.encode("usage", forKey: .type)
                try body.encode(to: encoder)
            case .sessionCost(let body):
                try c.encode("session.cost", forKey: .type)
                try body.encode(to: encoder)
            case .mcpRequest(let body):
                try c.encode("mcp.request", forKey: .type)
                try body.encode(to: encoder)
            case .taskStarted(let body):
                try c.encode("task.started", forKey: .type)
                try body.encode(to: encoder)
            case .taskFinished(let body):
                try c.encode("task.finished", forKey: .type)
                try body.encode(to: encoder)
            case .taskDiff(let body):
                try c.encode("task.diff", forKey: .type)
                try body.encode(to: encoder)
            case .taskMerged(let body):
                try c.encode("task.merged", forKey: .type)
                try body.encode(to: encoder)
            case .taskMergeCheck(let body):
                try c.encode("task.merge_check", forKey: .type)
                try body.encode(to: encoder)
            case .taskHandedOff(let body):
                try c.encode("task.handed_off", forKey: .type)
                try body.encode(to: encoder)
            case .draftProgress(let body):
                try c.encode("draft.progress", forKey: .type)
                try body.encode(to: encoder)
            case .draftDone(let body):
                try c.encode("draft.done", forKey: .type)
                try body.encode(to: encoder)
            case .taskProgress(let body):
                try c.encode("task.progress", forKey: .type)
                try body.encode(to: encoder)
            case .taskCleaned(let body):
                try c.encode("task.cleaned", forKey: .type)
                try body.encode(to: encoder)
            case .taskTokenRequest(let body):
                try c.encode("task.token_request", forKey: .type)
                try body.encode(to: encoder)
            case .secretsRequest(let body):
                try c.encode("secrets.request", forKey: .type)
                try body.encode(to: encoder)
            case .unknown(let type):
                try c.encode(type, forKey: .type)
            }
        }
    }

