    /// Server → runner.
    public enum ServerToRunner: Codable, Hashable, Sendable {
        case sessionOpen(ServerToRunnerSessionOpen)
        case sessionResize(ServerToRunnerSessionResize)
        case sessionKill(ServerToRunnerSessionKill)
        case sessionEventsSubscribe(ServerToRunnerSessionEventsSubscribe)
        case sessionInput(ServerToRunnerSessionInput)
        case sessionReplay(ServerToRunnerSessionReplay)
        case runnerUpdate(ServerToRunnerRunnerUpdate)
        case agentLogin(ServerToRunnerAgentLogin)
        case runnerRestart
        case mcpResponse(ServerToRunnerMcpResponse)
        case taskFinish(ServerToRunnerTaskFinish)
        case taskDiff(ServerToRunnerTaskDiff)
        case taskMergeCheck(ServerToRunnerTaskMergeCheck)
        case taskMerge(ServerToRunnerTaskMerge)
        case taskHandoff(ServerToRunnerTaskHandoff)
        case draftRun(ServerToRunnerDraftRun)
        case draftCancel(ServerToRunnerDraftCancel)
        case taskCleanup(ServerToRunnerTaskCleanup)
        case taskToken(ServerToRunnerTaskToken)
