        public func encode(to encoder: Encoder) throws {
            var c = encoder.container(keyedBy: TypeKey.self)
            switch self {
            case .sessionOpen(let body):
                try c.encode("session.open", forKey: .type)
                try body.encode(to: encoder)
            case .sessionResize(let body):
                try c.encode("session.resize", forKey: .type)
                try body.encode(to: encoder)
            case .sessionKill(let body):
                try c.encode("session.kill", forKey: .type)
                try body.encode(to: encoder)
            case .sessionEventsSubscribe(let body):
                try c.encode("session.events.subscribe", forKey: .type)
                try body.encode(to: encoder)
            case .sessionInput(let body):
                try c.encode("session.input", forKey: .type)
                try body.encode(to: encoder)
            case .sessionReplay(let body):
                try c.encode("session.replay", forKey: .type)
                try body.encode(to: encoder)
            case .runnerUpdate(let body):
                try c.encode("runner.update", forKey: .type)
                try body.encode(to: encoder)
            case .agentLogin(let body):
                try c.encode("agent.login", forKey: .type)
                try body.encode(to: encoder)
            case .runnerRestart:
                try c.encode("runner.restart", forKey: .type)
            case .mcpResponse(let body):
                try c.encode("mcp.response", forKey: .type)
                try body.encode(to: encoder)
            case .taskFinish(let body):
                try c.encode("task.finish", forKey: .type)
                try body.encode(to: encoder)
            case .taskDiff(let body):
                try c.encode("task.diff", forKey: .type)
                try body.encode(to: encoder)
            case .taskMergeCheck(let body):
                try c.encode("task.merge_check", forKey: .type)
                try body.encode(to: encoder)
            case .taskMerge(let body):
                try c.encode("task.merge", forKey: .type)
                try body.encode(to: encoder)
            case .taskHandoff(let body):
                try c.encode("task.handoff", forKey: .type)
                try body.encode(to: encoder)
            case .draftRun(let body):
                try c.encode("draft.run", forKey: .type)
                try body.encode(to: encoder)
            case .draftCancel(let body):
                try c.encode("draft.cancel", forKey: .type)
                try body.encode(to: encoder)
            case .taskCleanup(let body):
                try c.encode("task.cleanup", forKey: .type)
                try body.encode(to: encoder)
            case .taskToken(let body):
                try c.encode("task.token", forKey: .type)
                try body.encode(to: encoder)
            case .secretsReply(let body):
                try c.encode("secrets.reply", forKey: .type)
                try body.encode(to: encoder)
            case .unknown(let type):
                try c.encode(type, forKey: .type)
